```kotlin
// @file: Reservation outcome variants produced by the vendor gateway.
// @consumers: OrderFulfillmentPipeline

package com.example.reservations

/** @purpose Closed variant space for reservation outcomes. */
sealed interface ReservationOutcome {
    /** @purpose Successful reservation with vendor-assigned identifier. */
    data class Reserved(val reservationId: String) : ReservationOutcome

    /** @purpose Out-of-stock signal, terminal for the current attempt. */
    data object OutOfStock : ReservationOutcome

    /** @purpose Retryable transient failure carrying the root cause. */
    data class TransientFailure(val cause: Throwable) : ReservationOutcome
}

/**
 * @purpose Route a reservation outcome to a downstream policy.
 * @return Policy decision derived from the outcome variant.
 */
fun routeOutcome(outcome: ReservationOutcome): PolicyDecision = when (outcome) {
    is ReservationOutcome.Reserved         -> PolicyDecision.Confirm(outcome.reservationId)
    is ReservationOutcome.OutOfStock       -> PolicyDecision.RejectTerminal
    is ReservationOutcome.TransientFailure -> PolicyDecision.RetryLater(outcome.cause)
}
```

```kotlin // @file: Contract surface for vendor reservation integration. // @consumers: OrderFulfillmentPipeline
package com.example.reservations
/** * @purpose Gateway for interacting with a vendor API. * @invariant Retry Policy: idempotent methods retried up to 3 times. * @invariant Error Policy: all HTTP 5xx are wrapped into VendorNetworkError. */ interface VendorGateway { /** * @purpose Synchronous reservation registration: lock stock at the vendor warehouse. * @invariant Idempotency-Ref must be propagated unchanged across retries. * @param idempotencyKey UUIDv4 preventing duplicated reservations during network retries. * @throws VendorStockError Item is out of stock at the vendor. * @return Internal identifier of the created reservation in the vendor system. * @sideEffect Network: POST /v2/reservations * @sideEffect Dispatch: Dispatchers.IO */ suspend fun reserveStock(idempotencyKey: String): String } ```

```kotlin
// @file: HTTP implementation of the VendorGateway contract.
// @consumers: OrderFulfillmentPipeline
// @tasks: TASK-1187

package com.example.reservations.http

import com.example.reservations.VendorGateway
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * @purpose HTTP adapter for interacting with a vendor API.
 * @implements {VendorGateway} in com/example/reservations/VendorGateway.kt
 */
class HttpVendorGateway(
    private val _httpClient: HttpClient,
) : VendorGateway {

    /** @see {VendorGateway#reserveStock} in com/example/reservations/VendorGateway.kt */
    override suspend fun reserveStock(idempotencyKey: String): String {
        require(idempotencyKey.isNotBlank()) { "[HttpVendorGateway#reserveStock] idempotencyKey must be non-blank" }

        //region START_VENDOR_API_CALL — invariant: vendor deduplicates retries only when X-Idempotency-Ref is preserved exactly
        return try {
            withContext(Dispatchers.IO) {
                _httpClient.post(
                    path = "/v2/reservations",
                    headers = mapOf("X-Idempotency-Ref" to idempotencyKey),
                ).reservationId
            }
        } catch (cancel: CancellationException) {
            throw cancel
        } catch (cause: Throwable) {
            throw VendorNetworkError("[HttpVendorGateway#reserveStock] Reservation failed", cause)
        }
        //endregion END_VENDOR_API_CALL
    }
}
```

```kotlin
// @file: Parallel fetch of independent vendor prices.
// @consumers: PricingAggregator

package com.example.pricing

import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.supervisorScope
import kotlinx.coroutines.withContext

/**
 * @purpose Fetch prices from multiple vendors in parallel, tolerating individual failures.
 * @invariant One vendor failure does not cancel siblings; failed vendors surface as null in the map.
 * @param vendorIds Vendor identifiers to query.
 * @return Map from vendor id to price; null value = vendor failed for this call.
 * @sideEffect Network: parallel GETs to /v1/prices per vendor.
 */
suspend fun fetchVendorPrices(vendorIds: List): Map =
    withContext(Dispatchers.IO) {
        supervisorScope {
            vendorIds.associateWith { id ->
                async {
                    try {
                        priceClient.retrievePrice(id)
                    } catch (cancel: CancellationException) {
                        throw cancel
                    } catch (cause: Throwable) {
                        null
                    }
                }
            }.mapValues { (_, deferred) -> deferred.await() }
        }
    }
```

```kotlin
// @file: Strategy selection helpers for path-aware processing.
// @consumers: StrategyPlanner

package com.example.strategy

/** @purpose Configuration for choosing a processing strategy. */
data class DecideStrategyConfig(
    /** @purpose Path to the target resource | @invariant Absent value triggers fallback strategy */
    val path: String?,
)

/**
 * @purpose Decide a processing strategy based on whether the config carries a path.
 * @param config Configuration parameters.
 * @return Identifier of the chosen strategy.
 */
fun decideStrategy(config: DecideStrategyConfig): String =
    config.path?.let { path -> resolveStrategyFor(path) } ?: "fallback"
